import base64, json, os, runpy, shutil, subprocess, sys, time
from pathlib import Path
os.environ.update(HF_HUB_DISABLE_XET="1", HF_HUB_DISABLE_PROGRESS_BARS="1", HF_HOME="/tmp/e52-hf",
                  OMP_NUM_THREADS="2", VLLM_WORKER_MULTIPROC_METHOD="spawn")
started = time.time()
out = Path("/kaggle/working/e67-c")
out.mkdir(parents=True, exist_ok=True)
subprocess.run(["nvidia-smi"], check=True)
root = Path("/tmp/aimo-e52")
for name, encoded in json.loads('{"datagen/perturb/steer.py": "", "datagen/perturb/sample.py": "", "datagen/perturb/answers.py": "", "datagen/extract_features.py": "", "datagen/tokenizer_check.py": "", "scripts/kaggle_process_guard.py": "", "data/e67/directions.npz": "", "data/e67/pool.parquet": "", "protocols/E67_PROTOCOL.md": "", "data/probe_system_prompt.txt": ""}').items():
    dest = root / name
    dest.parent.mkdir(parents=True, exist_ok=True)
    dest.write_bytes(base64.b64decode(encoded))
subprocess.run([sys.executable, "-m", "pip", "install", "--no-cache-dir", "-q", *['transformers==5.13.0', 'accelerate==1.13.0', 'huggingface-hub==1.22.0', 'tokenizers==0.22.2', 'safetensors==0.8.0', 'scikit-learn==1.8.0', 'joblib==1.5.3']], check=True)
freeze = subprocess.run([sys.executable, "-m", "pip", "freeze"], capture_output=True, text=True, check=True)
(out / "environment.txt").write_text(freeze.stdout)
from huggingface_hub import snapshot_download
snapshot_download("Qwen/Qwen3.5-4B")  # once; the two processes then load offline (e67-timing v2 lost one to the Hub)
guard = runpy.run_path(str(root / "scripts/kaggle_process_guard.py"))["run_guarded"]
argv = ['datagen/perturb/steer.py', '--pool', 'data/e67/pool.parquet', '--directions', 'data/e67/directions.npz', '--system-prompt-file', 'data/probe_system_prompt.txt', '--max-hours', '9.0', '--local-files-only', '--out-dir', '/kaggle/working/e67-c', '--problem-keys', '0c92ee468a97153c', '150379f24091989c', '21664e8724631d8e', '2af2382163387efd', '3b42c306bbdb303b', '418cd2130291e730', '4dfd5aa3057a3545', '5da7e3afedefcfee', '7074eabb90202e6c', '7f09dc8099a1e3b9', '8e45a80d28562586', 'acc6de91da35bd46', 'c012c6845e62b0e4', 'ca6393350e84c775', 'f30661f0306f6294']
# One process per T4, each on half of this kernel's problems.
launcher = ("import os, subprocess, sys\n"
            f"argv = {argv!r}\n"
            "procs = [subprocess.Popen([sys.executable, *argv, '--num-shards', '2', '--shard-index', str(i)],\n"
            "         env={**os.environ, 'CUDA_VISIBLE_DEVICES': str(i),\n"
            "              'PYTORCH_CUDA_ALLOC_CONF': 'expandable_segments:True', 'HF_HUB_OFFLINE': '1'}) for i in (0, 1)]\n"
            "sys.exit(max(p.wait() for p in procs))")
result = guard([sys.executable, "-c", launcher], root, out / "steer.log", timeout=34200.0)
(out / "execution.json").write_text(json.dumps({**result, "end_to_end_seconds": time.time() - started}, indent=2))
raise SystemExit(result["exit_code"])
